static const int kGalaxyAlreadyHere=1000;
static const char galaxyAlreadyHereText[]="We're already here, Captain.";
static const char galaxyAlreadyHereVoice[]="9000-2-0-0-14";
static void loadGalaxyOverrides() {
	static Common::String strings[ARRAYSIZE(galaxyPlaces)][6];
	Common::File file;
	if(!file.open(Common::FSNode(ConfMan.getPath("sq5_voice_path").join("galaxy-map.json")))) return;
	if(file.size()>256*1024) return;
	Common::String body;while(!file.eos())body+=file.readLine();
	Common::JSONValue *doc=Common::JSON::parse(body);
	if(!doc||!doc->isArray()){delete doc;return;}
	for(auto *item:doc->asArray()) {
		if(!item->isObject()||!item->hasChild("key")||!item->child("key")->isString())continue;
		for(uint i=0;i<ARRAYSIZE(galaxyPlaces);++i) {
			auto &p=galaxyPlaces[i];if(item->child("key")->asString()!=p.key)continue;
			const char *names[]={"name","system","description","refusal","followup","destroyed_description"};
			const char **dest[]={&p.name,&p.system,&p.description,&p.refusal,&p.followup,&p.destroyedDescription};
			for(int j=0;j<6;++j)if(item->hasChild(names[j])&&item->child(names[j])->isString()) {
				strings[i][j]=item->child(names[j])->asString();*dest[j]=strings[i][j].c_str();
			}
			auto number=[&](const char *key,int &dest,int lo,int hi) {
				if(item->hasChild(key)&&item->child(key)->isNumber())dest=CLIP<int>((int)item->child(key)->asNumber(),lo,hi);
			};
			number("size",p.size,16,80);number("orbit",p.orbit,1,6);number("angle",p.angle,0,359);number("sprite",p.sprite,0,12);
			number("rings",p.rings,1,6);number("suns",p.suns,1,2);number("moons",p.moons,0,12);
		}
	}
	delete doc;
}
